 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            points = set()
            while q:
                y, x = q.popleft()
                points.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, points))
    return result


def _l_corner(points):
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    for r, vr in ((r0, 1), (r1, -1)):
        for c, hc in ((c0, 1), (c1, -1)):
            shape = ({(r, x) for x in range(c0, c1 + 1)} |
                     {(y, c) for y in range(r0, r1 + 1)})
            if points == shape:
                return r, c, vr, hc
    return None


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    markers = [(len(p), color, p, _l_corner(p))
               for color, p in comps if _l_corner(p) is not None]
    if not markers:
        return [row[:] for row in grid]

    # The prominent L is the directional marker. Its open corner indicates
    # the side of the grid containing the object to recolor.
    _, marker_color, marker, corner = max(markers, key=lambda z: z[0])
    r, c, vertical_arm_down, horizontal_arm_right = corner
    out = [row[:] for row in grid]
    candidates = []
    for color, points in comps:
        if color == marker_color:
            continue
        rr = [y for y, x in points]
        cc = [x for y, x in points]
        # Select components wholly on the side opposite each L arm.
        if vertical_arm_down == 1:
            vertical_side = max(rr) < r
        else:
            vertical_side = min(rr) > r
        if horizontal_arm_right == 1:
            horizontal_side = max(cc) < c
        else:
            horizontal_side = min(cc) > c
        if vertical_side and horizontal_side:
            candidates.append((len(points), points))

    if not candidates:
        return out
    target = max(candidates, key=lambda item: item[0])[1]
    for y, x in target:
        out[y][x] = marker_color
    return out
